attribute vec4 aPosition;
attribute vec4 aTexCoord;
uniform mat4 uTexMatrix;
varying vec2 vTexCoord;
void main() {
    gl_Position = aPosition;
    vTexCoord = (uTexMatrix * aTexCoord).xy;
}

#extension GL_OES_EGL_image_external : require
precision highp float;
varying vec2 vTexCoord;
uniform samplerExternalOES uTexture;
uniform int uSourceMode;

const float HLG_A = 0.17883277;
const float HLG_B = 0.28466892;
const float HLG_C = 0.55991073;
const vec3 LUMA_709 = vec3(0.2126, 0.7152, 0.0722);
const float LIVE_SATURATION = 0.85;

float srgbToLinearChannel(float value) {
    return value <= 0.04045 ? value / 12.92 : pow((value + 0.055) / 1.055, 2.4);
}

vec3 srgbToLinear(vec3 color) {
    return vec3(
        srgbToLinearChannel(color.r),
        srgbToLinearChannel(color.g),
        srgbToLinearChannel(color.b)
    );
}

float hlgInverseOetfChannel(float value) {
    return value <= 0.5
        ? (value * value) / 3.0
        : (exp((value - HLG_C) / HLG_A) + HLG_B) / 12.0;
}

float hlgOetfChannel(float value) {
    float safeValue = max(value, 0.0);
    return safeValue <= (1.0 / 12.0)
        ? sqrt(3.0 * safeValue)
        : HLG_A * log(12.0 * safeValue - HLG_B) + HLG_C;
}

vec3 hlgToLinear(vec3 color) {
    return vec3(
        hlgInverseOetfChannel(color.r),
        hlgInverseOetfChannel(color.g),
        hlgInverseOetfChannel(color.b)
    );
}

vec3 linearToHlg(vec3 color) {
    return vec3(
        hlgOetfChannel(color.r),
        hlgOetfChannel(color.g),
        hlgOetfChannel(color.b)
    );
}

float rollOffHighlightLuma(float value) {
    const float knee = 0.66;
    const float ceiling = 0.88;
    if (value <= knee) {
        return value;
    }

    float headroom = ceiling - knee;
    return knee + headroom * (1.0 - exp(-(value - knee) / headroom));
}

float softClipChannel(float value) {
    const float knee = 0.84;
    if (value <= knee) {
        return value;
    }

    float headroom = 1.0 - knee;
    return knee + headroom * (1.0 - exp(-(value - knee) / headroom));
}

vec3 toneMapSdrToPseudoHdr(vec3 linearColor) {
    vec3 exposureColor = linearColor * 0.82;
    float luma = dot(exposureColor, LUMA_709);
    float midGain = mix(1.0, 1.28, smoothstep(0.12, 0.64, luma));
    float highlightProtect = mix(1.0, 0.68, smoothstep(0.58, 0.96, luma));
    float gain = midGain * highlightProtect;
    vec3 boosted = exposureColor * gain;
    float boostedLuma = dot(boosted, LUMA_709);
    float rolledLuma = rollOffHighlightLuma(boostedLuma);
    if (boostedLuma > 0.0001) {
        boosted *= rolledLuma / boostedLuma;
    }
    boosted = vec3(
        softClipChannel(boosted.r),
        softClipChannel(boosted.g),
        softClipChannel(boosted.b)
    );

    float finalLuma = dot(boosted, LUMA_709);
    float chromaKeep = mix(1.0, LIVE_SATURATION, smoothstep(0.48, 0.90, finalLuma));
    vec3 neutral = vec3(dot(boosted, LUMA_709));
    return mix(neutral, boosted, chromaKeep);
}

void main() {
    vec3 sampled = clamp(texture2D(uTexture, vTexCoord).rgb, 0.0, 1.0);
    vec3 sceneLinear;
    if (uSourceMode == 1) {
        sceneLinear = hlgToLinear(sampled);
    } else {
        sceneLinear = toneMapSdrToPseudoHdr(srgbToLinear(sampled));
    }

    vec3 sceneLuma = vec3(dot(sceneLinear, LUMA_709));
    sceneLinear = mix(sceneLuma, sceneLinear, LIVE_SATURATION);
    vec3 encoded = linearToHlg(clamp(sceneLinear, 0.0, 12.0));
    gl_FragColor = vec4(clamp(encoded, 0.0, 1.0), 1.0);
}

